PR_NUMBER=$(env -u GITHUB_TOKEN gh pr view --json number --jq '.number')
REPO_OWNER=$(env -u GITHUB_TOKEN gh repo view --json owner --jq '.owner.login')
REPO_NAME=$(env -u GITHUB_TOKEN gh repo view --json name --jq '.name')
echo "PR=$PR_NUMBER  REPO=$REPO_OWNER/$REPO_NAME"
echo ""
echo "=== Unresolved review threads ==="
env -u GITHUB_TOKEN gh api graphql -f query="
{
  repository(owner: \"$REPO_OWNER\", name: \"$REPO_NAME\") {
    pullRequest(number: $PR_NUMBER) {
      reviewThreads(first: 100) {
        nodes { id isResolved comments(first: 10) { nodes { author { login } body path line } } }
      }
    }
  }
}" --jq '.data.repository.pullRequest.reviewThreads.nodes[] | select(.isResolved==false) | {id, author: .comments.nodes[0].author.login, path: .comments.nodes[0].path, line: .comments.nodes[0].line, body: .comments.nodes[0].body[0:200]}'
echo ""
echo "=== Reviews (state + author + body head) ==="
env -u GITHUB_TOKEN gh api repos/$REPO_OWNER/$REPO_NAME/pulls/$PR_NUMBER/reviews --jq '.[] | {author: .user.login, state: .state, body_head: (.body[0:300])}'
echo ""
echo "=== Issue-level comments (bot summaries) ==="
env -u GITHUB_TOKEN gh api repos/$REPO_OWNER/$REPO_NAME/issues/$PR_NUMBER/comments --jq '.[] | {author: .user.login, body_head: (.body[0:200])}'

